create table public.brazil_minimum_wage(id uuid primary key default gen_random_uuid(),effective_from date not null,effective_to date,amount_minor_units bigint not null,source_reference text not null,verified boolean not null default true,unique(effective_from));
create table public.flight_payroll_personal_deductions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,category text not null check(category in('ALIMONY','UNION_DUES','WELLHUB','HEALTH_PLAN','HEALTH_PLAN_COPAY','LOAN','MUTUAL_AID_FUND','OTHER')),calculation_type text not null check(calculation_type in('FIXED','PERCENTAGE','PERCENTAGE_MINIMUM_WAGE','MANUAL_VARIABLE')),amount_minor_units bigint,percentage_basis_points integer,base_type text,deductible_from_irrf_base boolean not null default false,deductible_from_inss_base boolean not null default false,effective_from date not null,effective_to date,active boolean not null default true,source_type text not null check(source_type in('USER_CONFIRMED','PAYROLL_CONFIRMED','DOCUMENT_SOURCE')),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.flight_payroll_tax_estimates(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,import_id uuid not null unique references public.flight_schedule_imports(id) on delete cascade,gross_amount_minor_units bigint not null,inss_amount_minor_units bigint not null,irrf_amount_minor_units bigint not null,personal_deductions_minor_units bigint not null,net_amount_minor_units bigint not null,tax_status text not null check(tax_status in('COMPLETE','INCOMPLETE','REVIEW_REQUIRED')),provenance jsonb not null default '{}'::jsonb);
alter table public.brazil_minimum_wage enable row level security; alter table public.flight_payroll_personal_deductions enable row level security; alter table public.flight_payroll_tax_estimates enable row level security;
create policy minimum_wage_read on public.brazil_minimum_wage for select to authenticated using(true); create policy personal_deductions_owner on public.flight_payroll_personal_deductions for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy tax_estimates_owner on public.flight_payroll_tax_estimates for select to authenticated using(user_id=auth.uid());
grant select,insert,update,delete on public.brazil_minimum_wage,public.flight_payroll_personal_deductions,public.flight_payroll_tax_estimates to service_role; grant select on public.brazil_minimum_wage,public.flight_payroll_personal_deductions,public.flight_payroll_tax_estimates to authenticated;
insert into public.brazil_minimum_wage(effective_from,amount_minor_units,source_reference) values('2026-01-01',162100,'Ato oficial vigente 2026') on conflict do nothing;
insert into public.flight_payroll_personal_deductions(user_id,name,category,calculation_type,percentage_basis_points,base_type,deductible_from_irrf_base,effective_from,source_type,notes) select distinct user_id,'Pensão alimentícia','ALIMONY','PERCENTAGE_MINIMUM_WAGE',15000,'BRAZIL_MINIMUM_WAGE',true,'2026-01-01'::date,'USER_CONFIRMED','Confirmação de perfil: 150% do salário mínimo.' from public.flight_schedule_imports on conflict do nothing;
